//! Explicit full baseline mode adapter; ordinary defaults remain unchanged.
use super::{capture_command,policy_stdout_work,bounded,NativeReportWork,OUTER_WATCHDOG,MAX_STDERR};use crate::{native_baseline_update_wire::Terminal,selected_exclusions_wire::MAX_HEADER,report_work::Work};use std::{io::{self,Write},path::PathBuf,process::Command};
fn invalid(s:&str)->io::Error{io::Error::new(io::ErrorKind::InvalidInput,s)}
#[derive(Debug)]struct Invocation{program:PathBuf,root:PathBuf,mode:crate::native_baseline_update_wire::Mode,no_gen:bool,selectors:Vec<String>}
fn invocation(args:&[String])->io::Result<Invocation>{
 let(mut program,mut at)=(None,0);let mut ordinary=vec!["analyze".to_owned()];
 while let Some(arg)=args.get(at){at+=1;if arg=="--native-dmbc"{let p=PathBuf::from(args.get(at).ok_or_else(||invalid("native executable missing"))?);at+=1;if !p.is_absolute()||program.replace(p).is_some(){return Err(invalid("baseline needs one absolute native executable"))}}else{ordinary.push(arg.clone())}}
 let parsed=crate::cli_arguments::parse(ordinary);if parsed.cmd!="baseline"{return Err(invalid("native baseline requires baseline command"))}
 // The original baseline branch only consumes the three mode flags. All other
 // ordinary flags/positionals are inert here; CHECK owns their distinct semantics.
 let has=|name:&str|parsed.flags.iter().any(|flag|flag==name);let mode=if has("--seed"){crate::native_baseline_update_wire::Mode::Seed}else if has("--update"){crate::native_baseline_update_wire::Mode::Update}else if has("--migrate"){crate::native_baseline_update_wire::Mode::Migrate}else{return Err(invalid("native baseline requires --update, --seed or --migrate"))};
 let program=program.ok_or_else(||invalid("baseline needs --native-dmbc"))?;
 Ok(Invocation{program,root:std::fs::canonicalize(crate::cli_arguments::find_root(parsed.root))?,mode,no_gen:std::env::var("DQ_BASELINE_NO_GEN").is_ok(),selectors:parsed.lints})
}

#[derive(Debug)]struct DeliveryFailure{committed:Option<(u64,bool)>,verified:bool,primary:io::Error}
impl std::fmt::Display for DeliveryFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{match self.committed{Some((n,g))=>write!(f,"native baseline {} file(s) committed, GEN committed={}, evidence verified={}: {}",n,g,self.verified,self.primary),None=>write!(f,"native baseline commit status unknown; source may have changed: {}",self.primary)}}}impl std::error::Error for DeliveryFailure{fn source(&self)->Option<&(dyn std::error::Error+'static)>{Some(&self.primary)}}
fn failure(primary:io::Error,committed:Option<(u64,bool)>,verified:bool)->io::Error{if primary.get_ref().is_some_and(|e|e.is::<DeliveryFailure>()){return primary}io::Error::new(primary.kind(),DeliveryFailure{committed,verified,primary})}
struct Delivered<'a>{diagnostics:&'a[u8],report:&'a[u8],committed:(u64,bool)}
fn text<'a>(bytes:&'a[u8],request:&Invocation,work:&NativeReportWork,opstderr:&[u8])->io::Result<Delivered<'a>>{let line=bytes.iter().take(MAX_HEADER).position(|b|*b==b'\n').ok_or_else(||invalid("baseline lacks bounded completed header"))?;work.temporary(0,MAX_HEADER.checked_mul(8).and_then(|n|n.checked_add(65536)).ok_or_else(||work.overflow())?)?;let t:Terminal=serde_json::from_slice(&bytes[..line]).map_err(io::Error::other)?;t.require(&request.root,request.mode,request.no_gen,crate::full_registry_check_selection_wire::SelectionBinding::for_selectors(&request.selectors)?)?;let commit=(t.committed_files,t.generation_committed);let result=(||{let payload=&bytes[line+1..];let dn=usize::try_from(t.diagnostics.as_ref().map_or(0,|s|s.length)).map_err(|_|invalid("baseline diagnostic extent overflow"))?;let rn=usize::try_from(t.report.length).map_err(|_|invalid("baseline report extent overflow"))?;if dn.checked_add(rn)!=Some(payload.len()){return Err(invalid("baseline payload extents differ"))}let(diagnostics,report)=payload.split_at(dn);if t.diagnostics.as_ref().is_some_and(|s|s.hash.0!=xxhash_rust::xxh3::xxh3_128(diagnostics))||t.report.hash.0!=xxhash_rust::xxh3::xxh3_128(report)||!report.ends_with(b"\n")||std::str::from_utf8(report).is_err(){return Err(invalid("baseline streams differ from sealed text"))}if !opstderr.is_empty(){return Err(failure(io::Error::new(io::ErrorKind::Unsupported,"operational stderr has no separately qualified log sink; no completed semantic output delivered"),Some(commit),true))}Ok(Delivered{diagnostics,report,committed:commit})})();result.map_err(|e|failure(e,Some(commit),false))}
fn publish(d:Delivered<'_>,out:&mut impl Write,err:&mut impl Write)->io::Result<()>{err.write_all(d.diagnostics).and_then(|()|out.write_all(d.report)).map_err(|e|failure(e,Some(d.committed),true))}
fn run(args:&[String],out:&mut impl Write,err:&mut impl Write)->io::Result<u8>{let r=invocation(args)?;let mut command=Command::new(&r.program);command.arg("analyze-baseline-update").arg("--workspace").arg(&r.root).arg("--mode").arg(match r.mode{crate::native_baseline_update_wire::Mode::Update=>"update",crate::native_baseline_update_wire::Mode::Seed=>"seed",crate::native_baseline_update_wire::Mode::Migrate=>"migrate"});if r.no_gen{command.arg("--no-gen");}if !r.selectors.is_empty(){command.arg("--lint").args(&r.selectors);}let(status,captured,stderr)=capture_command(command,OUTER_WATCHDOG,policy_stdout_work,|r|bounded(r,MAX_STDERR)).map_err(|e|failure(e,None,false))?;err.write_all(&stderr).map_err(|e|failure(e,None,false))?;let Some(0)=status.code()else{return incomplete_exit(status.code(),err)};let work=captured.policy_work.as_ref().ok_or_else(||failure(invalid("baseline lost physical output allowance"),None,false))?;let delivered=text(&captured.bytes,&r,work,&stderr).map_err(|e|failure(e,None,false))?;publish(delivered,out,err)?;Ok(0)}
fn incomplete_exit(status:Option<i32>,err:&mut impl Write)->io::Result<u8>{writeln!(err,"native baseline commit status unknown; source may have changed; child did not return a completed baseline terminal (status {:?})",status).map_err(|e|failure(e,None,false))?;Ok(if status==Some(75){75}else{2})}
pub(super)fn cli(args:&[String])->std::process::ExitCode{match run(args,&mut io::stdout().lock(),&mut io::stderr().lock()){Ok(n)=>std::process::ExitCode::from(n),Err(e)=>{eprintln!("analyze native baseline update: {e}");std::process::ExitCode::from(2)}}}

#[cfg(test)]mod controls{use super::*;
 #[test]fn native_baseline_requires_explicit_mode_backend_and_valid_backend_values_before_child(){for tail in[vec!["--update","--unimplemented-baseline-option"],vec!["--update","--native-dmbc"],vec!["--update","--root"]]{let mut args=vec!["baseline".into()];args.extend(tail.into_iter().map(str::to_owned));assert!(invocation(&args).is_err());}}

 #[test]fn baseline_selectors_preserve_shared_comma_group_exclusion_and_root_order_without_starting_a_child(){
  let executable=if cfg!(windows){"E:/actual/dmbc.exe"}else{"/actual/dmbc"};let root=std::env::current_dir().unwrap();
  let args=vec!["baseline".into(),"--native-dmbc".into(),executable.into(),"--root".into(),root.join("missing-earlier-root").to_string_lossy().into_owned(),"--update".into(),"--lint".into(),"scheduler,sem".into(),"-sem/handlers".into(),"--lint".into(),"scheduler".into(),"--root".into(),root.to_string_lossy().into_owned(),"--no-cache".into(),"--rehash".into()];
  let actual=invocation(&args).unwrap();assert_eq!(actual.root,std::fs::canonicalize(root).unwrap());assert_eq!(actual.selectors,["scheduler","sem","-sem/handlers","scheduler"]);assert_eq!(actual.mode,crate::native_baseline_update_wire::Mode::Update);
 }

 #[test]fn baseline_known_check_only_flags_keep_the_original_inert_baseline_semantics(){let executable=if cfg!(windows){"E:/actual/dmbc.exe"}else{"/actual/dmbc"};let root=std::env::current_dir().unwrap();let mut args=vec!["baseline".into(),"--native-dmbc".into(),executable.into(),"--root".into(),root.to_string_lossy().into_owned(),"--update".into()];let before=invocation(&args).unwrap();args.extend(["--changed-only","--raw","--ci","--timing","--no-selftest","--unused","--no-unused","--unknown-original-baseline-flag","ignored-positional"].map(str::to_owned));let after=invocation(&args).unwrap();assert_eq!(before.root,after.root);assert_eq!(before.mode,after.mode);assert_eq!(before.selectors,after.selectors);assert_eq!(before.no_gen,after.no_gen);}
 #[test]fn baseline_unknown_commit_preserves_first_actual_output_io(){let error=failure(io::Error::from_raw_os_error(1450),None,false);assert_eq!(error.kind(),io::Error::from_raw_os_error(1450).kind());let owner=error.get_ref().unwrap().downcast_ref::<DeliveryFailure>().unwrap();assert_eq!(owner.primary.raw_os_error(),Some(1450));assert_eq!(owner.committed,None);assert!(!owner.verified);assert!(error.to_string().contains("source may have changed"));}
 #[test]fn baseline_child_nonzero_or_signal_keeps_status_and_never_silently_claims_no_mutation(){for status in[Some(75),Some(2),Some(1),None]{let mut err=Vec::new();assert_eq!(incomplete_exit(status,&mut err).unwrap(),if status==Some(75){75}else{2});let text=String::from_utf8(err).unwrap();assert!(text.contains("commit status unknown"));assert!(text.contains("source may have changed"));}struct Stop;impl Write for Stop{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}let error=incomplete_exit(None,&mut Stop).unwrap_err();let owner=error.get_ref().unwrap().downcast_ref::<DeliveryFailure>().unwrap();assert_eq!(owner.primary.raw_os_error(),Some(1450));assert_eq!(owner.committed,None);assert!(!owner.verified);}
 #[test]fn baseline_mode_precedence_matches_original_seed_then_update_then_migrate(){let executable=if cfg!(windows){"E:/actual/dmbc.exe"}else{"/actual/dmbc"};let root=std::env::current_dir().unwrap();for(flags,expected)in[(vec!["--migrate"],crate::native_baseline_update_wire::Mode::Migrate),(vec!["--migrate","--update"],crate::native_baseline_update_wire::Mode::Update),(vec!["--update","--seed","--migrate"],crate::native_baseline_update_wire::Mode::Seed),(vec!["--seed","--update","--seed"],crate::native_baseline_update_wire::Mode::Seed)]{let mut args=vec!["baseline".into(),"--native-dmbc".into(),executable.into(),"--root".into(),root.to_string_lossy().into_owned()];args.extend(flags.into_iter().map(str::to_owned));assert_eq!(invocation(&args).unwrap().mode,expected);}}

}
